      if (snapshot) {
        renderer3d.updateBoard(snapshot, layers);
      }
    } else {
      // Switch back to 2D
      is3DActive = false;
      view3dBtn.classList.remove('active');

      // Show 2D canvas, dispose 3D
      canvas.style.display = '';
